/* SP-Berner Supplier Management · local-first application */
const DB_NAME='spberner-suppliers', DB_VERSION=2;
const SPECIALTIES=['Paletizadores y encajado','AGV / AMR e intralogística','Láser y marcado','Componentes','Final de línea','Robótica y automatización'];
const STATUSES=['Pendiente de contacto','Contactado','Visita programada','Visitado','Pendiente de información','En evaluación','En seguimiento','Homologado','No homologado','Archivado'];
const PHOTO_CATEGORIES=['Fotografía general','Fotografía técnica','Fotografía de visita'];
const DOC_CATEGORIES=['Documento comercial','Documento técnico','Certificado o referencia','Otro archivo'];
const FILES_RECOMMENDED=25*1024*1024, FILES_MAX=100*1024*1024;
let objectUrls=[];
const COMMON=[
 ['Empresa y capacidades', [['Actividad y productos principales','text'],['Número de empleados','text'],['Ingeniería propia','choice'],['Fabricación propia y porcentaje subcontratado','text'],['Sectores y mercados principales','text'],['Experiencia exportando a Europa / España','text'],['Referencias de proyectos similares','text'],['Certificaciones e idiomas','text']]],
 ['Ingeniería y personalización', [['Soluciones personalizadas','choice'],['Disciplinas de ingeniería propias','text'],['Diseño mecánico / eléctrico y programación PLC/HMI/robots','text'],['Simulación 3D, pruebas, prototipos y laboratorio','text'],['Adaptación a instalaciones existentes','text'],['Experiencia con productos plásticos / piezas de inyección','text'],['Observaciones y ejemplos de proyectos','textarea']]],
 ['Componentes y calidad', [['Marcas de PLC, HMI, servos y variadores','text'],['Marcas de sensores, neumática, robótica y visión','text'],['Acepta marcas y modelos especificados por SP-Berner','choice'],['Sistema de calidad y certificaciones','text'],['Pruebas, inspecciones y trazabilidad','text'],['Gestión de no conformidades','text']]],
 ['Proyectos y capacidad', [['Gestión de ofertas, alcance y modificaciones','text'],['Responsable de proyecto y comunicación de avances','text'],['Validación interna, FAT y SAT','text'],['Plazos de oferta, ingeniería, fabricación y entrega','text'],['Capacidad mensual y proyectos simultáneos','text'],['Técnicos disponibles y proyectos urgentes','text']]],
 ['Software y postventa', [['Software y licencias necesarios','text'],['Entrega de fuentes, proyectos editables y contraseñas','text'],['Restricciones y dependencia de fabricante','text'],['Instalación y asistencia en Europa','text'],['Soporte remoto/presencial, tiempos y horario','text'],['Repuestos, garantía y formación','text'],['Manuales y mantenimiento preventivo','text']]],
 ['Experiencia y referencias', [['Proyectos similares y número de instalaciones','text'],['Clientes y referencias relevantes','text'],['Experiencia en Europa / España / plástico','text'],['Posibilidad de visitar una instalación existente','choice']]]
];
const TECH={
 'Paletizadores y encajado':[['Tipo de solución y productos manipulados','textarea'],['Cadencia nominal y garantizada','text'],['Formatos, dimensiones y peso máximo','text'],['Altura / palés por hora / tiempo de cambio','text'],['Robot, ejes y tipo de pinza','text'],['Visión, detección y recuperación de errores','textarea'],['Integración con transportadores y equipos de línea','textarea'],['Operarios, espacio, consumos y seguridad','textarea']],
 'AGV / AMR e intralogística':[['Tipología y cargas transportadas','textarea'],['Capacidad, dimensiones y velocidad','text'],['Autonomía, batería y tiempo de carga','text'],['Navegación y precisión de posicionamiento','text'],['Gestión de flota / software e integraciones','textarea'],['Funcionamiento interior/exterior y ambiente','textarea'],['Seguridad, obstáculos y convivencia con personas','textarea'],['Instalación, soporte y escalabilidad','textarea']],
 'Láser y marcado':[['Proceso (marcado, corte, soldadura) y materiales','textarea'],['Fuente láser, potencia y vida útil','text'],['Área de trabajo y precisión','text'],['Cadencia y calidad de resultado','text'],['Extracción de humos y seguridad láser','textarea'],['Integración, software y trazabilidad','textarea'],['Muestras y pruebas disponibles','textarea']],
 'Componentes':[['Familias y referencias ofrecidas','textarea'],['Fabricante, origen y alternativas','textarea'],['Especificaciones y certificaciones','textarea'],['Disponibilidad y plazo de suministro','text'],['MOQ, precios y escalados','text'],['Trazabilidad y control de calidad','textarea'],['Compatibilidad con estándares SP-Berner','textarea']],
 'Final de línea':[['Equipos incluidos y alcance de línea','textarea'],['Formatos y productos compatibles','textarea'],['Cadencia y disponibilidad garantizada','text'],['Transportadores, acumulación y buffers','textarea'],['Integración con paletizado y embalaje','textarea'],['Cambios de formato y limpieza','textarea'],['Seguridad, operación y mantenimiento','textarea']],
 'Robótica y automatización':[['Aplicaciones y sectores de experiencia','textarea'],['Marcas de robot y alcance/carga','text'],['Programación, simulación y offline programming','textarea'],['Visión, pinzas y periféricos','textarea'],['Integración PLC, seguridad y comunicaciones','textarea'],['Cadencia y precisión','text'],['FAT, documentación y soporte','textarea']]
};
const CRITERIA=[['Capacidad técnica',25],['Ingeniería y personalización',20],['Calidad y componentes',15],['Gestión de proyectos',15],['Plazos y capacidad',10],['Software y autonomía',5],['Instalación y postventa',10]];
let db, suppliers=[], currentPage='inicio', toastTimer, saveTimer;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;for(const n of ['suppliers','contacts','visits','evaluations','config','attachments'])if(!d.objectStoreNames.contains(n))d.createObjectStore(n,{keyPath:'id'});};req.onblocked=()=>say('Cierra otras pestañas de esta aplicación para aplicar la actualización de almacenamiento.');req.onsuccess=()=>{req.result.onversionchange=()=>req.result.close();resolve(req.result);};req.onerror=()=>reject(req.error);});}
function all(store){return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function put(store,row){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(row);tx.oncomplete=()=>resolve(row);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Transacción cancelada'));});}
function del(store,id){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
function uid(){return crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;}
function say(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600);}
function status(t){$('#saveStatus').textContent=t;}
function escList(list){return (list||[]).map(esc).join(', ');}
function dateShort(d){return d?new Date(d+'T00:00:00').toLocaleDateString('es-ES',{day:'2-digit',month:'short',year:'numeric'}):'Sin fecha';}
function selected(items,chosen){return items.map(x=>`<option ${chosen===x?'selected':''} value="${esc(x)}">${esc(x)}</option>`).join('');}
function pageHead(kicker,title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function button(label,action,style=''){return `<button class="button ${style}" data-action="${action}">${label}</button>`;}
function getStatus(s){return `<span class="pill ${['Pendiente de contacto','Pendiente de información','No homologado'].includes(s.status)?'pending':''}">${esc(s.status||'Pendiente de contacto')}</span>`;}
function supplierCard(s){return `<article class="supplier-card" data-open="${s.id}"><div class="card-top"><div><h3>${esc(s.name)}</h3><p>${esc([s.city,s.country].filter(Boolean).join(', ')||'Ubicación pendiente')} · ${esc(s.code||'ID local')}</p></div>${getStatus(s)}</div><div class="muted">${esc(s.contactName||'Sin contacto principal')}${s.email?' · '+esc(s.email):''}</div><div class="tags">${(s.specialties||[]).map(x=>`<span class="tag">${esc(x)}</span>`).join('')||'<span class="tag">Sin especialidad</span>'}</div></article>`;}
async function refresh(){suppliers=await all('suppliers');$('#supplierCount').textContent=suppliers.length;render();}
function render(){if(currentPage==='inicio')renderHome();if(currentPage==='proveedores')renderSuppliers();if(currentPage==='evaluaciones')renderEvaluations();if(currentPage==='ajustes')renderSettings();document.querySelectorAll('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===currentPage));}
async function renderHome(){const visits=await all('visits'), evals=await all('evaluations'), tasks=[];const visited=new Set(visits.map(v=>v.supplierId));const latest=[...visits].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,5);$('#main').innerHTML=`${pageHead('VISTA GENERAL','Panel de proveedores','Resumen de la información guardada en este dispositivo.',button('＋ Nuevo proveedor','new-supplier'))}<section class="stats"><div class="stat"><div class="stat-label">Proveedores registrados</div><div class="stat-num">${suppliers.length}</div><div class="stat-foot">Fichas locales</div></div><div class="stat"><div class="stat-label">Proveedores visitados</div><div class="stat-num">${visited.size}</div><div class="stat-foot">Con al menos una visita</div></div><div class="stat"><div class="stat-label">Visitas registradas</div><div class="stat-num">${visits.length}</div><div class="stat-foot">Reuniones documentadas</div></div><div class="stat"><div class="stat-label">Evaluaciones iniciadas</div><div class="stat-num">${evals.length}</div><div class="stat-foot">Guardadas localmente</div></div></section><div class="content-grid"><section class="panel"><div class="panel-title"><h2>Actividad reciente</h2><span>${visits.length} visitas en total</span></div>${latest.length?`<div class="list">${latest.map(v=>{const s=suppliers.find(x=>x.id===v.supplierId);return `<div class="list-row" data-open="${v.supplierId}"><div class="list-main"><b>${esc(s?.name||'Proveedor')}</b><small>${dateShort(v.date)}${v.objective?' · '+esc(v.objective):''}</small></div><span class="pill">Visita</span></div>`}).join('')}</div>`:`<div class="empty"><b>Aún no hay visitas registradas</b>Registra una visita desde la ficha de un proveedor.</div>`}</section><section class="panel"><div class="panel-title"><h2>Accesos rápidos</h2><span>Acciones habituales</span></div><div class="quick-actions"><button class="quick-action" data-action="new-supplier">＋ Añadir proveedor<small>Crear una ficha básica</small></button><button class="quick-action" data-page="proveedores">◉ Ver proveedores<small>Buscar y editar fichas</small></button><button class="quick-action" data-page="evaluaciones">✓ Evaluaciones<small>Completar valoración</small></button><button class="quick-action" data-page="ajustes">▤ Almacenamiento<small>Estado y persistencia local</small></button></div><div class="warning">Los datos, fotografías y documentos se guardan en este navegador y dispositivo. Informes y copias de seguridad se incorporarán en fases posteriores.</div></section></div>`;}
function renderSuppliers(){const needle=($('#supplierSearch')?.value||'').trim().toLowerCase();const statusFilter=$('#statusFilter')?.value||'';const filtered=suppliers.filter(s=>(!needle||[s.name,s.code,s.city,s.country,s.email,...(s.specialties||[])].join(' ').toLowerCase().includes(needle))&&(!statusFilter||s.status===statusFilter));$('#main').innerHTML=`${pageHead('REGISTRO','Proveedores','Fichas, contactos y visitas en un único lugar.',button('＋ Nuevo proveedor','new-supplier'))}<div class="searchbar"><input class="input" id="supplierSearch" placeholder="Buscar por nombre, ciudad, país o especialidad…" value="${esc(needle)}" aria-label="Buscar proveedores"><select class="select" id="statusFilter" style="max-width:245px"><option value="">Todos los estados</option>${STATUSES.map(s=>`<option ${statusFilter===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="panel-title"><h2>${filtered.length} ${filtered.length===1?'proveedor':'proveedores'}</h2><span>Selecciona una ficha para ver su historial</span></div>${filtered.length?`<div class="card-grid">${filtered.map(supplierCard).join('')}</div>`:`<div class="empty"><b>${suppliers.length?'No hay coincidencias':'Empieza por crear una ficha de proveedor'}</b>${suppliers.length?'Prueba con otro término o estado.':'Los campos se pueden completar después de la reunión.'}</div>`}`;$('#supplierSearch').addEventListener('input',e=>{const v=e.target.value;renderSuppliers();const n=$('#supplierSearch');n.focus();n.setSelectionRange(v.length,v.length);});$('#statusFilter').addEventListener('change',renderSuppliers);}
async function renderEvaluations(){const evals=await all('evaluations');const incomplete=evals.filter(e=>e.scores);$('#main').innerHTML=`${pageHead('VALORACIÓN','Evaluaciones','Puntuaciones ponderadas, requisitos obligatorios y condiciones comerciales.', '')}<section class="panel"><div class="panel-title"><h2>Evaluaciones por proveedor</h2><span>Escala de 1 a 5 · pesos configurables en Ajustes</span></div>${suppliers.length?`<div class="list">${suppliers.map(s=>{const e=evals.find(x=>x.supplierId===s.id);const scored=e?score(e):null;return `<div class="list-row" data-open="${s.id}"><div class="list-main"><b>${esc(s.name)}</b><small>${escList(s.specialties)||'Sin especialidad'} · ${e?'Última edición '+dateShort((e.updatedAt||'').slice(0,10)):'Sin evaluación'}</small></div><span class="rating-summary">${scored?scored.percent+'%':'—'}</span></div>`}).join('')}</div>`:`<div class="empty"><b>No hay proveedores que evaluar</b>Crea una ficha primero; podrás empezar una evaluación parcial sin completar todos los campos.</div>`}</section><section class="panel"><div class="panel-title"><h2>Cómo se calcula</h2></div><p class="muted">Cada criterio tiene un peso porcentual. La aplicación calcula el promedio ponderado usando únicamente los criterios puntuados y lo convierte a porcentaje sobre 5. Los criterios sin respuesta no reducen la puntuación; el porcentaje de cobertura indica cuánto de la ponderación está cumplimentada. Los requisitos obligatorios se presentan aparte y no modifican la puntuación.</p></section>`;}
async function renderSettings(){let cfg=await all('config');const config=cfg[0]||{};const estimate=await navigator.storage?.estimate?.().catch(()=>null);const persistent=await navigator.storage?.persisted?.().catch(()=>false);const usage=estimate?.usage||0,quota=estimate?.quota||0,percent=quota?Math.min(100,usage/quota*100):0;$('#main').innerHTML=`${pageHead('DISPOSITIVO','Ajustes y almacenamiento','La base de datos se queda en este navegador. No se envían datos a servidores.', '')}<div class="content-grid"><section class="panel"><div class="panel-title"><h2>Almacenamiento local</h2><span>${persistent?'Persistencia concedida':'Persistencia no confirmada'}</span></div><div class="stat-label">Uso estimado del sitio</div><div class="storage-meter"><span style="width:${percent.toFixed(1)}%"></span></div><p class="muted">${usage?`${(usage/1024/1024).toFixed(1)} MB utilizados de ${(quota/1024/1024/1024).toFixed(1)} GB estimados.`:'Este navegador no informa de una cuota de almacenamiento.'} El espacio disponible depende del dispositivo y del navegador.</p><div class="toolbar"><button class="button" data-action="request-persist">Solicitar almacenamiento persistente</button><button class="button secondary" data-action="refresh-storage">Actualizar estado</button></div>${persistent?'<p class="muted">El navegador ha concedido almacenamiento persistente para este sitio.</p>':'<div class="warning">El navegador puede eliminar datos del sitio si el dispositivo tiene poco espacio o se borran sus datos de navegación. Instala y abre la app en HTTPS y realiza copias periódicas; la exportación completa llegará en una fase posterior.</div>'}</section><section class="panel"><div class="panel-title"><h2>Identificación y criterios</h2></div><div class="form-grid"><div class="field"><label>Empresa</label><input class="input" data-config="company" value="${esc(config.company||'SP-Berner')}"></div><div class="field"><label>Feria o evento</label><input class="input" data-config="event" value="${esc(config.event||'Feria industrial · China')}"></div><div class="field"><label>Año</label><input class="input" data-config="year" value="${esc(config.year||'2026')}"></div><div class="field"><label>Prefijo de identificador</label><input class="input" data-config="prefix" value="${esc(config.prefix||'CF26')}"></div></div><h3 style="font-size:12px;margin:20px 0 10px">Ponderación de criterios (%)</h3><div class="form-grid">${CRITERIA.map(([name,weight],i)=>`<div class="field"><label>${esc(name)}</label><input class="input" type="number" min="0" max="100" data-weight="${i}" value="${config.weights?.[i]??weight}"></div>`).join('')}</div><p id="weightSum" class="muted"></p></section></div><section class="panel"><div class="panel-title"><h2>Fases disponibles</h2></div><p class="muted">Fases 1–3: estructura de PWA, fichas y contactos, visitas, formularios de evaluación y almacenamiento local. Las fotos/adjuntos, informes PDF, exportación Excel y copias ZIP corresponden a fases posteriores.</p></section>`;document.querySelectorAll('[data-config]').forEach(i=>i.addEventListener('change',()=>saveConfig()));document.querySelectorAll('[data-weight]').forEach(i=>i.addEventListener('input',()=>{const vals=[...document.querySelectorAll('[data-weight]')].map(x=>Number(x.value)||0);$('#weightSum').textContent=`Suma actual: ${vals.reduce((a,b)=>a+b,0)}%${vals.reduce((a,b)=>a+b,0)===100?' · válida':' · ajusta los pesos para sumar 100%'}`;}));document.querySelectorAll('[data-weight]').forEach(i=>i.dispatchEvent(new Event('input')));}
async function saveConfig(){const old=(await all('config'))[0]||{id:'app'};old.id='app';for(const i of document.querySelectorAll('[data-config]'))old[i.dataset.config]=i.value;old.weights=[...document.querySelectorAll('[data-weight]')].map(x=>Math.max(0,Math.min(100,Number(x.value)||0)));old.updatedAt=new Date().toISOString();await put('config',old);$('#weightSum').textContent=`Suma actual: ${old.weights.reduce((a,b)=>a+b,0)}%${old.weights.reduce((a,b)=>a+b,0)===100?' · válida':' · ajusta los pesos para sumar 100%'}`;status('Configuración guardada');}
function field(label,name,value='',type='text',extra=''){const attr=type==='textarea'?`<textarea class="textarea" name="${name}" ${extra}>${esc(value)}</textarea>`:`<input class="input" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;return `<div class="field"><label>${label}</label>${attr}</div>`;}
function showModal(content){const d=$('#modal');if(d.open)d.close();releaseObjectUrls();d.innerHTML=content;d.showModal();d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());}
function releaseObjectUrls(){objectUrls.forEach(URL.revokeObjectURL);objectUrls=[];}
function fileUrl(blob){const url=URL.createObjectURL(blob);objectUrls.push(url);return url;}
function formatBytes(n){if(!Number.isFinite(n))return '—';if(n<1024)return `${n} B`;if(n<1024*1024)return `${(n/1024).toFixed(0)} KB`;return `${(n/1024/1024).toFixed(1)} MB`;}
function fileKind(a){return a.kind==='photo'||a.mimeType?.startsWith('image/')?'photo':'document';}
function downloadLink(a,label='Descargar'){const url=fileUrl(a.blob);return `<a class="button secondary small" href="${url}" download="${esc(a.fileName)}">${label}</a>`;}
function photoCard(a){return `<article class="media-card" data-file-visit="${esc(a.visitId||'')}"><button class="media-thumb" data-action="preview-photo" data-id="${a.id}" aria-label="Ampliar ${esc(a.title||a.fileName)}"><img src="${fileUrl(a.blob)}" alt="${esc(a.title||a.fileName)}" loading="lazy"></button><div class="media-info"><b>${esc(a.title||a.fileName)}</b><small>${esc(a.description||a.fileName)}</small><small>${esc(a.category||'Fotografía general')} · ${dateShort((a.addedAt||'').slice(0,10))}</small><div class="toolbar"><button class="button secondary small" data-action="edit-attachment" data-id="${a.id}">Editar</button><button class="button danger small" data-action="delete-attachment" data-id="${a.id}">Eliminar</button></div></div></article>`;}
function documentRow(a){const url=fileUrl(a.blob),canPreview=a.mimeType==='application/pdf';return `<div class="file-row" data-file-visit="${esc(a.visitId||'')}"><div class="file-icon">${esc((a.fileName.split('.').pop()||'FILE').slice(0,4).toUpperCase())}</div><div class="file-detail"><b>${esc(a.title||a.fileName)}</b><small>${esc(a.fileName)} · ${formatBytes(a.size)} · ${esc(a.category||'Otro archivo')} · ${dateShort((a.addedAt||'').slice(0,10))}</small>${a.description?`<small>${esc(a.description)}</small>`:''}</div><div class="toolbar">${canPreview?`<a class="button secondary small" href="${url}" target="_blank" rel="noopener" aria-label="Abrir PDF ${esc(a.fileName)}">Abrir PDF</a>`:''}<a class="button secondary small" href="${url}" download="${esc(a.fileName)}">Descargar</a><button class="button secondary small" data-action="edit-attachment" data-id="${a.id}">Editar</button><button class="button danger small" data-action="delete-attachment" data-id="${a.id}">Eliminar</button></div></div>`;}
async function attachmentMarkup(supplierId,visitId){const rows=(await all('attachments')).filter(a=>a.supplierId===supplierId&&(!visitId||a.visitId===visitId));const photos=rows.filter(a=>fileKind(a)==='photo');const docs=rows.filter(a=>fileKind(a)==='document');const visitSelect=visitId?'':`<select class="select" id="attachmentVisitFilter" aria-label="Filtrar documentos por visita"><option value="">Todas las visitas</option>${(await all('visits')).filter(v=>v.supplierId===supplierId).map(v=>`<option value="${v.id}">${dateShort(v.date)}${v.objective?' · '+esc(v.objective):''}</option>`).join('')}</select>`;return `<section class="panel media-panel" style="box-shadow:none"><div class="panel-title"><div><h2>${visitId?'Archivos de esta visita':'Fotografías y documentos'}</h2><span>${rows.length} archivos · almacenados localmente</span></div><button class="button secondary small" data-action="manage-files" data-id="${supplierId}" ${visitId?`data-visit="${visitId}"`:''}>Gestionar archivos</button></div><div class="media-actions"><button class="button" data-action="upload-camera" data-id="${supplierId}" ${visitId?`data-visit="${visitId}"`:''}>▣ Tomar fotografía</button><button class="button secondary" data-action="upload-photos" data-id="${supplierId}" ${visitId?`data-visit="${visitId}"`:''}>＋ Añadir fotografías</button><button class="button secondary" data-action="upload-docs" data-id="${supplierId}" ${visitId?`data-visit="${visitId}"`:''}>＋ Adjuntar documentos</button></div>${visitSelect}${photos.length?`<div class="photo-grid">${photos.slice(0,8).map(photoCard).join('')}</div>`:'<div class="empty compact-empty">Aún no hay fotografías adjuntas.</div>'}${docs.length?`<div class="file-list">${docs.slice(0,6).map(documentRow).join('')}</div>`:'<div class="empty compact-empty">Aún no hay documentos adjuntos.</div>'}<p class="field-hint">Los archivos quedan guardados en este dispositivo. Los archivos grandes pueden agotar el almacenamiento del navegador; realiza copias externas de los originales.</p></section>`;}
async function uploadForm(supplierId,visitId,kind,capture=false){const s=suppliers.find(x=>x.id===supplierId);if(!s)return;const isPhoto=kind==='photo';const categories=isPhoto?PHOTO_CATEGORIES:DOC_CATEGORIES;const accepts=isPhoto?'image/*':'.pdf,.xls,.xlsx,.doc,.docx,.ppt,.pptx,.jpg,.jpeg,.png,.webp,*/*';showModal(`<div class="modal-head"><div><div class="eyebrow">${isPhoto?'AÑADIR FOTOGRAFÍAS':'ADJUNTAR DOCUMENTOS'}</div><h2>${visitId?'Visita · ':''}${esc(s.name)}</h2></div><button class="close" data-close>×</button></div><div class="modal-scroll"><div class="form-grid"><div class="field"><label>Clasificación</label><select class="select" id="fileCategory">${categories.map((x,i)=>`<option ${visitId&&i===(isPhoto?2:0)?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Sección técnica (opcional)</label><input class="input" id="fileSection" placeholder="Ej. Visión artificial"></div><div class="field full"><label>Descripción (opcional, se aplicará a los archivos seleccionados)</label><textarea class="textarea" id="fileDescription" placeholder="Describe qué aparece o qué contiene…"></textarea></div></div><div class="upload-picker"><label class="button" for="filePicker">${capture?'Abrir cámara':'Seleccionar archivos'}</label><input id="filePicker" type="file" accept="${accepts}" ${capture?'capture="environment"':'multiple'} hidden><p class="muted">${isPhoto?'Selecciona una imagen o usa la cámara del dispositivo. La cámara depende del navegador; si no se abre, usa “Añadir fotografías”.':'Se almacenan localmente y se podrán abrir o descargar con las apps instaladas.'} Admite selección múltiple cuando el navegador lo permita.</p><div id="uploadStatus" class="upload-status" role="status"></div></div></div><div class="modal-actions"><span class="muted">El archivo original se conserva sin compresión ni cambios.</span><button class="button secondary" data-close>Terminar</button></div>`);$('#modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{const d=$('#modal');if(d.open)d.close();visitId?openVisit(visitId):openSupplier(supplierId);});$('#filePicker').onchange=async ev=>{const input=ev.target,files=[...input.files];if(!files.length)return;await storeAttachments(files,supplierId,visitId,isPhoto);input.value='';};}
async function storeAttachments(files,supplierId,visitId,isPhoto){const statusEl=$('#uploadStatus');const category=$('#fileCategory').value,technicalSection=$('#fileSection').value.trim(),description=$('#fileDescription').value.trim();let saved=0,failed=0;let estimate=null;try{estimate=await navigator.storage?.estimate?.();}catch{}for(let i=0;i<files.length;i++){const file=files[i];try{statusEl.textContent=`Guardando ${i+1} de ${files.length}: ${file.name}`;await new Promise(resolve=>requestAnimationFrame(resolve));if(isPhoto&&!file.type.startsWith('image/'))throw new Error('El archivo seleccionado no es una imagen compatible.');if(file.size>FILES_MAX)throw new Error(`Supera el límite de esta versión: 100 MB (${formatBytes(file.size)}).`);if(file.size>FILES_RECOMMENDED)say(`${file.name}: archivo grande (${formatBytes(file.size)}); comprueba que quede espacio suficiente.`);if(file.size===0)throw new Error('El archivo está vacío.');if(estimate?.quota&&estimate.quota-estimate.usage<file.size*1.2)say(`Puede no haber espacio suficiente para ${file.name}; el navegador comprobará la escritura.`);const row={id:uid(),kind:isPhoto?'photo':'document',blob:file,fileName:file.name,mimeType:file.type||'application/octet-stream',size:file.size,title:file.name,description,category,technicalSection,addedAt:new Date().toISOString(),supplierId,visitId:visitId||null};await put('attachments',row);saved++;}catch(err){failed++;const reason=err?.name==='QuotaExceededError'?'espacio local insuficiente':err.message||'no se pudo leer o guardar';say(`${file.name}: ${reason}`);}}statusEl.textContent=`${saved} de ${files.length} archivo(s) guardados${failed?`; ${failed} no se guardaron`:''}.`;if(saved)status('Archivos guardados localmente');if(failed)status('Error al guardar archivos');if(saved&&!failed)setTimeout(()=>{const d=$('#modal');if(d.open)d.close();visitId?openVisit(visitId):openSupplier(supplierId);},900);}
async function manageAttachments(supplierId,visitId){const rows=(await all('attachments')).filter(a=>a.supplierId===supplierId&&(!visitId||a.visitId===visitId)).sort((a,b)=>b.addedAt.localeCompare(a.addedAt));const s=suppliers.find(x=>x.id===supplierId);const photos=rows.filter(a=>fileKind(a)==='photo');const docs=rows.filter(a=>fileKind(a)==='document');showModal(`<div class="modal-head"><div><div class="eyebrow">ARCHIVO LOCAL · ${esc(s?.name||'Proveedor')}</div><h2>${visitId?'Archivos de la visita':'Fotografías y documentos'}</h2></div><button class="close" data-close>×</button></div><div class="modal-scroll"><div class="media-actions"><button class="button" data-action="upload-camera" data-id="${supplierId}" ${visitId?`data-visit="${visitId}"`:''}>▣ Tomar fotografía</button><button class="button secondary" data-action="upload-photos" data-id="${supplierId}" ${visitId?`data-visit="${visitId}"`:''}>＋ Añadir fotografías</button><button class="button secondary" data-action="upload-docs" data-id="${supplierId}" ${visitId?`data-visit="${visitId}"`:''}>＋ Adjuntar documentos</button></div><input class="input" id="fileSearch" placeholder="Buscar por nombre, título o descripción…"><div class="form-section">Fotografías (${photos.length})</div>${photos.length?`<div class="photo-grid">${photos.map(photoCard).join('')}</div>`:'<div class="empty">Todavía no hay fotografías.</div>'}<div class="form-section">Documentos (${docs.length})</div>${docs.length?`<div class="file-list">${docs.map(documentRow).join('')}</div>`:'<div class="empty">Todavía no hay documentos.</div>'}</div><div class="modal-actions"><span class="muted">No se crean copias al mostrar archivos en la ficha.</span><button class="button secondary" data-close>Cerrar</button></div>`);$('#fileSearch').addEventListener('input',ev=>{const q=ev.target.value.toLowerCase();$('#modal').querySelectorAll('.media-card,.file-row').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(q));});}
async function openVisit(visitId){const visit=(await all('visits')).find(v=>v.id===visitId);if(!visit)return;const supplier=suppliers.find(s=>s.id===visit.supplierId);if(!supplier)return;const attachments=await attachmentMarkup(supplier.id,visit.id);showModal(`<div class="modal-head"><div><div class="eyebrow">VISITA · ${dateShort(visit.date)}</div><h2>${esc(supplier.name)}</h2></div><button class="close" data-close>×</button></div><div class="modal-scroll"><section class="panel" style="box-shadow:none"><div class="panel-title"><h2>${esc(visit.objective||'Reunión')}</h2><span>${esc(visit.time||'')}${visit.place?' · '+esc(visit.place):''}</span></div><div class="form-grid"><div class="field"><label>Participantes SP-Berner</label><div>${esc(visit.ourParticipants||'—')}</div></div><div class="field"><label>Participantes proveedor</label><div>${esc(visit.theirParticipants||'—')}</div></div><div class="field full"><label>Notas</label><div>${esc(visit.summary||'—')}</div></div><div class="field full"><label>Acuerdos y próximos pasos</label><div>${esc(visit.agreements||'—')}</div></div></div><div style="margin-top:14px"><button class="button secondary small" data-action="edit-visit" data-id="${visit.id}">Editar visita</button></div></section>${attachments}</div><div class="modal-actions"><span class="muted">Solo aparecen archivos asociados a esta visita.</span><button class="button secondary" data-close>Cerrar</button></div>`);}
async function editAttachment(id){const a=(await all('attachments')).find(x=>x.id===id);if(!a)return;showModal(`<div class="modal-head"><div><div class="eyebrow">DETALLES DEL ARCHIVO</div><h2>${esc(a.fileName)}</h2></div><button class="close" data-close>×</button></div><form id="attachmentEdit" class="form-grid"><div class="field"><label>Nombre visible</label><input class="input" name="title" value="${esc(a.title||a.fileName)}"></div><div class="field"><label>Clasificación</label><select class="select" name="category">${(fileKind(a)==='photo'?PHOTO_CATEGORIES:DOC_CATEGORIES).map(x=>`<option ${x===a.category?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field full"><label>Descripción</label><textarea class="textarea" name="description">${esc(a.description||'')}</textarea></div><div class="field"><label>Sección técnica</label><input class="input" name="technicalSection" value="${esc(a.technicalSection||'')}"></div><div class="field"><label>Archivo original</label><div class="muted">${esc(a.fileName)} · ${formatBytes(a.size)} · ${esc(a.mimeType)}</div></div></form><div class="modal-actions">${downloadLink(a,'Guardar original')}<button class="button" id="saveAttachment">Guardar descripción</button></div>`);$('#saveAttachment').onclick=async()=>{const data=Object.fromEntries(new FormData($('#attachmentEdit')).entries());await put('attachments',{...a,...data,updatedAt:new Date().toISOString()});$('#modal').close();a.visitId?openVisit(a.visitId):openSupplier(a.supplierId);say('Descripción actualizada; original intacto');};}
async function previewPhoto(id){const allFiles=await all('attachments');const a=allFiles.find(x=>x.id===id);if(!a)return;const rows=allFiles.filter(x=>x.supplierId===a.supplierId&&fileKind(x)==='photo').sort((x,y)=>x.addedAt.localeCompare(y.addedAt));const index=rows.findIndex(x=>x.id===id);showModal(`<div class="modal-head"><div><div class="eyebrow">FOTOGRAFÍA ${index+1} DE ${rows.length}</div><h2>${esc(a.title||a.fileName)}</h2></div><button class="close" data-close>×</button></div><div class="photo-view"><img src="${fileUrl(a.blob)}" alt="${esc(a.title||a.fileName)}"></div><p>${esc(a.description||'Sin descripción')}</p><p class="muted">${esc(a.fileName)} · ${formatBytes(a.size)} · ${dateShort((a.addedAt||'').slice(0,10))}${a.technicalSection?' · '+esc(a.technicalSection):''}</p><div class="modal-actions"><button class="button secondary" data-action="edit-attachment" data-id="${a.id}">Editar datos</button><div class="toolbar"><button class="button secondary" data-action="photo-prev" data-id="${rows[(index-1+rows.length)%rows.length].id}" ${rows.length<2?'disabled':''}>‹ Anterior</button><button class="button secondary" data-action="photo-next" data-id="${rows[(index+1)%rows.length].id}" ${rows.length<2?'disabled':''}>Siguiente ›</button></div></div>`);}
function supplierForm(s={}){const editing=!!s.id;showModal(`<div class="modal-head"><div><div class="eyebrow">${editing?'EDITAR FICHA':'NUEVA FICHA'}</div><h2>${editing?'Datos del proveedor':'Crear proveedor'}</h2></div><button class="close" data-close aria-label="Cerrar">×</button></div><div class="modal-scroll"><form id="supplierForm" class="form-grid"><div class="form-section">Empresa</div><div class="field full"><label>Nombre comercial *</label><input class="input" required name="name" value="${esc(s.name||'')}" placeholder="Nombre del proveedor"></div>${field('Nombre legal','legalName',s.legalName||'')}${field('País','country',s.country||'China')}${field('Provincia / región','region',s.region||'')}${field('Ciudad','city',s.city||'')}${field('Dirección','address',s.address||'')}${field('Página web','website',s.website||'','url')}${field('Correo electrónico','email',s.email||'','email')}${field('Teléfono','phone',s.phone||'','tel')}<div class="field"><label>Estado</label><select class="select" name="status">${selected(STATUSES,s.status||'Pendiente de contacto')}</select></div><div class="field"><label>Especialidades</label><div class="form-grid" style="gap:7px">${SPECIALTIES.map(x=>`<label style="font-weight:500;display:flex;gap:7px;align-items:center;font-size:11px"><input type="checkbox" name="specialties" value="${esc(x)}" ${(s.specialties||[]).includes(x)?'checked':''}>${esc(x)}</label>`).join('')}</div></div><div class="form-section">Contacto principal</div>${field('Nombre','contactName',s.contactName||'')}${field('Cargo','contactRole',s.contactRole||'')}${field('Correo','contactEmail',s.contactEmail||'','email')}${field('Teléfono','contactPhone',s.contactPhone||'','tel')}${field('Idioma','contactLanguage',s.contactLanguage||'')}${field('Observaciones generales','notes',s.notes||'','textarea') }</form></div><div class="modal-actions">${editing?`<button class="button danger small" data-action="delete-supplier" data-id="${s.id}">Eliminar ficha</button>`:'<span class="muted">La ficha puede guardarse con información parcial.</span>'}<div class="toolbar"><button class="button secondary" data-close>Cancelar</button><button class="button" id="saveSupplier">Guardar proveedor</button></div></div>`);$('#saveSupplier').onclick=async()=>{const f=$('#supplierForm');if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f).entries());const row={...s,...data,id:s.id||uid(),createdAt:s.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),specialties:[...f.querySelectorAll('[name=specialties]:checked')].map(x=>x.value)};delete row['specialties[]'];row.code=s.code||`SP-${new Date().getFullYear()}-${row.id.slice(0,5).toUpperCase()}`;await put('suppliers',row);$('#modal').close();await refresh();say('Proveedor guardado en este dispositivo');};}
async function openSupplier(id){const s=suppliers.find(x=>x.id===id);if(!s)return;const visits=(await all('visits')).filter(v=>v.supplierId===id).sort((a,b)=>(b.date||'').localeCompare(a.date||''));const contacts=(await all('contacts')).filter(x=>x.supplierId===id);const e=(await all('evaluations')).find(x=>x.supplierId===id)||{};const sc=score(e);const files=await attachmentMarkup(id);showModal(`<div class="modal-head"><div><div class="eyebrow">${esc(s.code||'PROVEEDOR')}</div><h2>${esc(s.name)}</h2><div class="detail-meta">${getStatus(s)}${(s.specialties||[]).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div></div><button class="close" data-close aria-label="Cerrar">×</button></div><div class="modal-scroll"><section class="panel" style="box-shadow:none"><div class="panel-title"><h2>Datos generales</h2><span>${esc([s.city,s.country].filter(Boolean).join(', '))}</span></div><div class="form-grid"><div class="field"><label>Contacto principal</label><div>${esc(s.contactName||'Pendiente')}${s.contactRole?' · '+esc(s.contactRole):''}</div></div><div class="field"><label>Contacto</label><div>${esc(s.contactEmail||s.email||'—')}${s.contactPhone||s.phone?' · '+esc(s.contactPhone||s.phone):''}</div></div><div class="field"><label>Web</label><div>${s.website?`<a href="${esc(s.website)}" target="_blank" rel="noopener">${esc(s.website)}</a>`:'—'}</div></div><div class="field"><label>Notas</label><div>${esc(s.notes||'—')}</div></div></div></section><section class="panel" style="box-shadow:none"><div class="panel-title"><h2>Contactos</h2><button class="button secondary small" data-action="new-contact" data-id="${id}">＋ Añadir contacto</button></div>${contacts.length?`<div class="list">${contacts.map(c=>`<div class="list-row"><div class="list-main"><b>${esc(c.name)}${c.role?' · '+esc(c.role):''}</b><small>${esc(c.email||'Sin correo')}${c.phone?' · '+esc(c.phone):''}${c.language?' · '+esc(c.language):''}</small></div><button class="button secondary small" data-action="edit-contact" data-id="${c.id}">Editar</button></div>`).join('')}</div>`:'<p class="muted">Añade más personas de contacto; el contacto principal está en los datos de empresa.</p>'}</section>${files}<section class="panel" style="box-shadow:none"><div class="panel-title"><h2>Visitas y reuniones</h2><span>${visits.length} registradas</span></div>${visits.length?`<div class="list">${visits.map(v=>`<div class="list-row"><div class="list-main"><b>${dateShort(v.date)}${v.time?' · '+esc(v.time):''}${v.place?' · '+esc(v.place):''}</b><small>${esc(v.objective||'Sin objetivo indicado')} · ${esc(v.summary||'Sin resumen')}</small></div><button class="button secondary small" data-action="open-visit" data-id="${v.id}">Ver archivos</button><button class="button secondary small" data-action="edit-visit" data-id="${v.id}">Editar</button></div>`).join('')}</div>`:'<div class="empty">Todavía no hay visitas. Puedes registrar varias reuniones para esta ficha.</div>'}</section><section class="panel" style="box-shadow:none"><div class="panel-title"><h2>Evaluación</h2><span>${sc?`${sc.percent}% completada`:'Aún sin iniciar'}</span></div>${sc?`<div class="summary-score"><b>${sc.rating?sc.rating.toFixed(2):'—'} / 5</b><span>Puntuación ponderada<br>${sc.coverage}% de criterios con nota</span></div>`:'<p class="muted">Evaluación parcial guardable en cualquier momento.</p>'}</section></div><div class="modal-actions"><button class="button secondary" data-action="edit-supplier" data-id="${id}">Editar ficha</button><div class="toolbar"><button class="button secondary" data-action="new-visit" data-id="${id}">＋ Registrar visita</button><button class="button" data-action="evaluate" data-id="${id}">✓ Evaluar proveedor</button></div></div>`);}
function contactForm(supplierId,c={}){showModal(`<div class="modal-head"><div><div class="eyebrow">CONTACTO DEL PROVEEDOR</div><h2>${c.id?'Editar':'Añadir'} contacto</h2></div><button class="close" data-close>×</button></div><form id="contactForm" class="form-grid">${field('Nombre *','name',c.name||'')}${field('Cargo','role',c.role||'')}${field('Correo','email',c.email||'','email')}${field('Teléfono','phone',c.phone||'','tel')}${field('Idioma','language',c.language||'')}${field('Observaciones','notes',c.notes||'','textarea')}</form><div class="modal-actions"><button class="button" id="saveContact">Guardar contacto</button></div>`);$('#saveContact').onclick=async()=>{const f=$('#contactForm');if(!f.reportValidity())return;const row=Object.fromEntries(new FormData(f).entries());await put('contacts',{...c,...row,id:c.id||uid(),supplierId,createdAt:c.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()});$('#modal').close();await openSupplier(supplierId);say('Contacto guardado');};}
function visitForm(id,v={}){const s=suppliers.find(x=>x.id===id);if(!s)return;showModal(`<div class="modal-head"><div><div class="eyebrow">${v.id?'EDITAR VISITA':'NUEVA REUNIÓN'} · ${esc(s.name)}</div><h2>Registro de visita</h2></div><button class="close" data-close>×</button></div><div class="modal-scroll"><form id="visitForm" class="form-grid"><div class="form-section">Reunión</div>${field('Fecha','date',v.date||new Date().toISOString().slice(0,10),'date')}${field('Hora','time',v.time||'','time')}${field('Lugar','place',v.place||'')}${field('Participantes SP-Berner','ourParticipants',v.ourParticipants||'')}${field('Participantes proveedor','theirParticipants',v.theirParticipants||'')}${field('Objetivo','objective',v.objective||'','textarea')}${field('Notas de reunión','summary',v.summary||'','textarea')}${field('Acuerdos y próximos pasos','agreements',v.agreements||'','textarea')}</form></div><div class="modal-actions"><span class="muted">Registro independiente; no modifica otras visitas.</span><button class="button" id="saveVisit">Guardar visita</button></div>`);$('#saveVisit').onclick=async()=>{const row=Object.fromEntries(new FormData($('#visitForm')).entries());await put('visits',{...v,...row,id:v.id||uid(),supplierId:id,createdAt:v.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()});$('#modal').close();await refresh();openSupplier(id);say('Visita guardada');};}
function score(e,weights){const ws=weights||e.weights||CRITERIA.map(x=>x[1]);const vals=e.scores||{};let total=0,used=0,raw=0;CRITERIA.forEach((x,i)=>{let val=Number(vals[i]);if(val>=1&&val<=5){const w=Number(ws[i])||0;total+=w*val/5;used+=w;raw+=w;}});return {percent:used?Math.round(total/used*100):0,rating:used?total/(used/100)/20:0,coverage:Math.round(used/(ws.reduce((a,b)=>a+(Number(b)||0),0)||100)*100)};}
async function loadWeights(){const cfg=(await all('config'))[0];return cfg?.weights?.length===CRITERIA.length?cfg.weights:CRITERIA.map(x=>x[1]);}
async function evaluate(id){
 const s=suppliers.find(x=>x.id===id);if(!s)return;
 const e=(await all('evaluations')).find(x=>x.supplierId===id)||{id:uid(),supplierId:id,answers:{},tech:{},scores:{},requirements:[],commercial:{}};
 const weights=await loadWeights();let tab='common';
 function commonBody(){return COMMON.map(([title,qs])=>`<div class="form-section">${title}</div>${qs.map(([q,t])=>`<div class="field ${t==='textarea'?'full':''}"><label>${q}</label>${t==='choice'?`<select class="select" data-answer="${esc(q)}"><option value="">Sin responder</option>${['Sí','Parcial','No','No aplica'].map(x=>`<option ${e.answers[q]===x?'selected':''}>${x}</option>`).join('')}</select>`:t==='textarea'?`<textarea class="textarea" data-answer="${esc(q)}">${esc(e.answers[q]||'')}</textarea>`:`<input class="input" data-answer="${esc(q)}" value="${esc(e.answers[q]||'')}">`}</div>`).join('')}`).join('');}
 function technicalBody(){const parts=(s.specialties||[]).flatMap(sp=>[`<div class="form-section">${esc(sp)}</div>`,...(TECH[sp]||[]).map(([q,type])=>`<div class="field ${type==='textarea'?'full':''}"><label>${esc(q)}</label><textarea class="textarea" data-tech="${esc(q)}" data-specialty="${esc(sp)}">${esc(e.tech?.[sp]?.[q]||'')}</textarea></div>`)]);return parts.join('')||'<div class="empty">Selecciona una especialidad en la ficha del proveedor para mostrar su formulario técnico.</div>';}
 function scoreBody(){return `<div class="field full"><div class="summary-score"><b id="liveRating">—</b><span id="liveCoverage">Introduce puntuaciones de 1 a 5.<br>Los criterios sin valorar no cuentan.</span></div></div>${CRITERIA.map(([name],i)=>`<div class="score-row"><label>${esc(name)}<small>Peso ${weights[i]}%</small></label><input type="range" min="1" max="5" step="1" data-score="${i}" value="${e.scores?.[i]||''}" aria-label="${esc(name)} puntuación"><span class="score-value">${e.scores?.[i]?e.scores[i]+'/5':'—'}</span></div>`).join('')}<div class="field full"><label>Observaciones de evaluación</label><textarea class="textarea" data-eval="comments">${esc(e.comments||'')}</textarea></div>`;}
 function mandatoryBody(){const qs=['Acepta trabajar con estándares y componentes definidos por SP-Berner','Entrega de programas fuente y documentación editable','Cumple normativa de seguridad aplicable en Europa','Puede dar soporte técnico durante instalación en Europa','Puede facilitar referencias verificables de proyectos similares'];return `<div class="field full"><div class="muted">Marca el resultado y registra la evidencia. Estos requisitos no se mezclan con la puntuación.</div></div>${qs.map((q,i)=>`<div class="check-row"><div>${q}</div><select class="select" data-requirement="${i}"><option value="">Pendiente</option>${['Cumple','Parcial','No cumple','No aplica'].map(x=>`<option ${e.requirements?.[i]?.status===x?'selected':''}>${x}</option>`).join('')}</select><textarea class="textarea" style="grid-column:1/-1;min-height:55px" placeholder="Evidencia / comentario" data-requirement-note="${i}">${esc(e.requirements?.[i]?.note||'')}</textarea></div>`).join('')}`;}
 function commercialBody(){return `<div class="form-section">Oferta y condiciones</div>${[['Precio','price'],['Moneda','currency'],['Desglose de costes','costBreakdown'],['Plazo de entrega','leadTime'],['Condiciones de pago','paymentTerms'],['Incoterm','incoterm'],['Garantía','warranty'],['Costes adicionales','extraCosts'],['Observaciones comerciales','comments']].map(([q,k])=>`<div class="field ${['costBreakdown','comments'].includes(k)?'full':''}"><label>${q}</label>${['costBreakdown','comments'].includes(k)?`<textarea class="textarea" data-commercial="${k}">${esc(e.commercial?.[k]||'')}</textarea>`:`<input class="input" data-commercial="${k}" value="${esc(e.commercial?.[k]||'')}">`}</div>`).join('')}`;}
 function renderForm(){
  const tabs=[['common','Formulario común'],['technical','Técnica'],['score','Puntuación'],['mandatory','Requisitos'],['commercial','Comercial']];
  const body=tab==='common'?commonBody():tab==='technical'?technicalBody():tab==='score'?scoreBody():tab==='mandatory'?mandatoryBody():commercialBody();
  showModal(`<div class="modal-head"><div><div class="eyebrow">EVALUACIÓN · ${esc(s.code||'')}</div><h2>${esc(s.name)}</h2></div><button class="close" data-close>×</button></div><div class="section-tabs">${tabs.map(([k,n])=>`<button class="${tab===k?'active':''}" data-tab="${k}">${n}</button>`).join('')}</div><div class="modal-scroll"><form id="evalForm" class="form-grid">${body}</form></div><div class="modal-actions"><span class="muted" id="evalSaved">Los cambios se guardan automáticamente</span><button class="button" data-close>Cerrar evaluación</button></div>`);
  $('#modal').querySelectorAll('[data-tab]').forEach(b=>b.onclick=async()=>{clearTimeout(saveTimer);await saveEval(e,id,weights);tab=b.dataset.tab;renderForm();});
  $('#evalForm').addEventListener('input',()=>{clearTimeout(saveTimer);$('#evalSaved').textContent='Guardando…';saveTimer=setTimeout(()=>saveEval(e,id,weights),400);});
  $('#evalForm').addEventListener('change',()=>{clearTimeout(saveTimer);$('#evalSaved').textContent='Guardando…';saveTimer=setTimeout(()=>saveEval(e,id,weights),100);});
  document.querySelectorAll('[data-score]').forEach(i=>i.oninput=()=>{i.nextElementSibling.textContent=i.value+'/5';updateLiveScore(weights);});updateLiveScore(weights);
 }
 renderForm();
}
function updateLiveScore(weights){const vals={};document.querySelectorAll('[data-score]').forEach(i=>{if(i.value)vals[i.dataset.score]=Number(i.value);});const v=score({scores:vals},weights);const el=$('#liveRating');if(el){el.textContent=v.rating?v.rating.toFixed(2)+' / 5':'—';$('#liveCoverage').innerHTML=`${v.percent}% · ${v.coverage}% del peso evaluado.<br>Solo se incluyen criterios con puntuación.`;}}
async function saveEval(e,id,weights){try{const form=$('#evalForm');if(!form)return;form.querySelectorAll('[data-answer]').forEach(x=>e.answers[x.dataset.answer]=x.value);form.querySelectorAll('[data-tech]').forEach(x=>{e.tech[x.dataset.specialty]??={};e.tech[x.dataset.specialty][x.dataset.tech]=x.value;});form.querySelectorAll('[data-score]').forEach(x=>{if(x.value)e.scores[x.dataset.score]=Number(x.value);else delete e.scores[x.dataset.score];});form.querySelectorAll('[data-eval]').forEach(x=>e[x.dataset.eval]=x.value);form.querySelectorAll('[data-commercial]').forEach(x=>e.commercial[x.dataset.commercial]=x.value);form.querySelectorAll('[data-requirement]').forEach(x=>{const i=Number(x.dataset.requirement);e.requirements[i]??={};e.requirements[i].status=x.value;});form.querySelectorAll('[data-requirement-note]').forEach(x=>{const i=Number(x.dataset.requirementNote);e.requirements[i]??={};e.requirements[i].note=x.value;});e.weights=weights;e.updatedAt=new Date().toISOString();await put('evaluations',e);$('#evalSaved').textContent='Guardado';status('Evaluación guardada');}catch(err){$('#evalSaved').textContent='Error al guardar';status('Error de almacenamiento');say(`No se pudo guardar: ${err.message}`);}}
document.addEventListener('click',async e=>{
 const nav=e.target.closest('[data-page]');if(nav){currentPage=nav.dataset.page;$('#sidebar').classList.remove('open');render();return;}
 const act=e.target.closest('[data-action]');if(act){const a=act.dataset.action,id=act.dataset.id;
  if(a==='new-supplier')supplierForm();
  if(a==='edit-supplier')supplierForm(suppliers.find(s=>s.id===id));
  if(a==='new-visit')visitForm(id);
  if(a==='edit-visit'){const v=(await all('visits')).find(x=>x.id===id);if(v)visitForm(v.supplierId,v);}
   if(a==='open-visit')openVisit(id);
  if(a==='new-contact')contactForm(id);
  if(a==='edit-contact'){const c=(await all('contacts')).find(x=>x.id===id);if(c)contactForm(c.supplierId,c);}
   if(a==='manage-files')manageAttachments(id,act.dataset.visit||null);
   if(a==='upload-camera')uploadForm(id,act.dataset.visit||null,'photo',true);
   if(a==='upload-photos')uploadForm(id,act.dataset.visit||null,'photo',false);
   if(a==='upload-docs')uploadForm(id,act.dataset.visit||null,'document',false);
   if(a==='edit-attachment')editAttachment(id);
   if(a==='preview-photo')previewPhoto(id);
   if(a==='photo-prev'||a==='photo-next')previewPhoto(id);
   if(a==='delete-attachment'&&confirm('¿Eliminar este archivo adjunto del dispositivo? Esta acción no se puede deshacer.')){const file=(await all('attachments')).find(x=>x.id===id);if(file){await del('attachments',id);$('#modal').close();say('Archivo eliminado');file.visitId?openVisit(file.visitId):manageAttachments(file.supplierId,null);}}
  if(a==='evaluate'){const d=$('#modal');if(d.open)d.close();evaluate(id);}
   if(a==='delete-supplier'&&confirm('¿Eliminar esta ficha y sus archivos, contactos, visitas y evaluación? Esta acción no se puede deshacer.')){for(const store of ['contacts','visits','evaluations','attachments'])for(const row of await all(store))if(row.supplierId===id)await del(store,row.id);await del('suppliers',id);$('#modal').close();await refresh();say('Ficha eliminada');}
  if(a==='request-persist'){if(!navigator.storage?.persist){say('Este navegador no permite solicitar persistencia');return;}const granted=await navigator.storage.persist();say(granted?'Persistencia concedida por el navegador':'El navegador no concedió persistencia');renderSettings();}
  if(a==='refresh-storage')renderSettings();return;
 }
 const card=e.target.closest('[data-open]');if(card){openSupplier(card.dataset.open);}
});
document.addEventListener('change',e=>{if(e.target.id==='attachmentVisitFilter'){const visit=e.target.value;$('#modal').querySelectorAll('.media-card,.file-row').forEach(row=>row.hidden=!!visit&&row.dataset.fileVisit!==visit);}});
$('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('open');
window.addEventListener('online',()=>{$('#connection').textContent='Conectado · datos locales';});window.addEventListener('offline',()=>{$('#connection').textContent='Sin conexión · datos locales';});
async function init(){try{db=await openDB();if(!window.isSecureContext&&location.hostname!=='localhost'&&location.protocol!=='file:')say('Abre la aplicación desde HTTPS para una instalación PWA fiable');if(navigator.storage?.persisted){const p=await navigator.storage.persisted();if(!p&&navigator.storage.persist){navigator.storage.persist().then(granted=>{if(granted)status('Almacenamiento persistente');}).catch(()=>{});}}status('Base local lista');$('#connection').textContent=navigator.onLine?'Conectado · datos locales':'Sin conexión · datos locales';await refresh();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(err){status('Error al abrir almacenamiento');$('#main').innerHTML=`<section class="panel"><h2>No se pudo iniciar la base local</h2><p>${esc(err.message)}. Usa un navegador moderno compatible con IndexedDB en una dirección HTTPS o localhost.</p></section>`;}}
init();
